public with sharing class ContactTriggerHandler {

    /**
     * Before insert: populate MailingCountry and LeadSource defaults from the related Account.
     */
    public static void beforeInsert(List<Contact> newContacts) {
        applyAccountDefaults(newContacts, true);
    }

    /**
     * Before update: populate MailingCountry default from the related Account
     * (LeadSource is only defaulted on insert, matching legacy behaviour).
     */
    public static void beforeUpdate(List<Contact> newContacts) {
        applyAccountDefaults(newContacts, false);
    }

    /**
     * After insert: for each Account that currently has no Phone, copy the Phone
     * from the first (in trigger order) newly inserted Contact of that Account
     * that has a Phone value. Only one DML update is issued for all qualifying
     * Accounts, regardless of batch size.
     */
    public static void afterInsert(List<Contact> newContacts) {
        Map<Id, String> firstPhoneByAccountId = new Map<Id, String>();

        for (Contact c : newContacts) {
            if (c.AccountId != null
                    && String.isNotBlank(c.Phone)
                    && !firstPhoneByAccountId.containsKey(c.AccountId)) {
                firstPhoneByAccountId.put(c.AccountId, c.Phone);
            }
        }

        if (firstPhoneByAccountId.isEmpty()) {
            return;
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Account a : [
            SELECT Id, Phone
            FROM Account
            WHERE Id IN :firstPhoneByAccountId.keySet()
        ]) {
            if (String.isBlank(a.Phone)) {
                a.Phone = firstPhoneByAccountId.get(a.Id);
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    private static void applyAccountDefaults(List<Contact> contacts, Boolean isInsertContext) {
        Set<Id> accountIds = new Set<Id>();

        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, BillingCountry, AccountSource
            FROM Account
            WHERE Id IN :accountIds
        ]);

        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }

            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }

            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }

            if (isInsertContext && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }
}
