/**
 * ExchangeRateClient
 *
 * Provides a simple wrapper around the FB_Exchange_Rates Named Credential to
 * retrieve live FX rates for a base currency against a set of quote
 * currencies.
 */
public with sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private static final String NAMED_CREDENTIAL = 'callout:FB_Exchange_Rates';
    private static final String ENDPOINT_PATH = '/v1/latest';
    private static final Pattern CURRENCY_CODE_PATTERN = Pattern.compile('^[A-Z]{3}$');

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // --- Validate inputs before any callout ---
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency must be supplied.');
        }

        String normalizedBase = normalizeCurrencyCode(baseCurrency);
        validateCurrencyCode(normalizedBase, 'base');

        Set<String> normalizedQuotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            String normalizedQuote = normalizeCurrencyCode(quote);
            validateCurrencyCode(normalizedQuote, 'quote');
            normalizedQuotes.add(normalizedQuote);
        }

        // --- Build request ---
        List<String> symbolList = new List<String>(normalizedQuotes);
        String symbolsParam = String.join(symbolList, ',');

        String endpoint = NAMED_CREDENTIAL + ENDPOINT_PATH
            + '?base=' + EncodingUtil.urlEncode(normalizedBase, 'UTF-8')
            + '&symbols=' + EncodingUtil.urlEncode(symbolsParam, 'UTF-8');

        HttpResponse response = sendRequest(endpoint);

        if (response.getStatusCode() == 503) {
            // Retry once with an identical request.
            response = sendRequest(endpoint);
        }

        if (response.getStatusCode() != 200) {
            throw new ExchangeRateException(
                'Exchange rate request failed with HTTP status code ' + response.getStatusCode() + '.'
            );
        }

        return parseRates(response.getBody(), normalizedQuotes);
    }

    private static HttpResponse sendRequest(String endpoint) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(endpoint);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');

        Http http = new Http();
        return http.send(request);
    }

    private static Map<String, Decimal> parseRates(String responseBody, Set<String> normalizedQuotes) {
        Map<String, Object> parsed;
        try {
            parsed = (Map<String, Object>) JSON.deserializeUntyped(responseBody);
        } catch (Exception ex) {
            throw new ExchangeRateException('Unable to parse exchange rate response body.');
        }

        if (parsed == null || !(parsed.get('rates') instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Exchange rate response did not contain a valid rates object.');
        }

        Map<String, Object> ratesRaw = (Map<String, Object>) parsed.get('rates');

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String code : normalizedQuotes) {
            Object rateValue = ratesRaw.get(code);
            if (rateValue == null) {
                throw new ExchangeRateException('No rate returned for requested currency ' + code + '.');
            }
            Decimal rateDecimal;
            try {
                rateDecimal = Decimal.valueOf(String.valueOf(rateValue));
            } catch (Exception ex) {
                throw new ExchangeRateException('Rate for currency ' + code + ' could not be parsed as a number.');
            }
            result.put(code, rateDecimal);
        }

        return result;
    }

    private static String normalizeCurrencyCode(String code) {
        return code == null ? null : code.trim().toUpperCase();
    }

    private static void validateCurrencyCode(String code, String label) {
        if (code == null || !CURRENCY_CODE_PATTERN.matcher(code).matches()) {
            throw new ExchangeRateException('Invalid ' + label + ' currency code: ' + code);
        }
    }
}
