/**
 * Service class providing utilities for grouping Contacts by the domain
 * portion of their email address.
 */
public with sharing class ContactDomainService {

    /**
     * Groups the contacts belonging to the given accounts by the domain part
     * of their email address (lower-cased).
     *
     * Contacts without an email address are excluded from the result.
     * A null or empty set of account ids returns an empty map.
     *
     * @param accountIds Set of Account Ids to query contacts for.
     * @return Map of lower-cased email domain -> List of Contacts.
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> result = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email != null
        ];

        for (Contact c : contacts) {
            String domain = extractDomain(c.Email);
            if (String.isBlank(domain)) {
                continue;
            }

            if (!result.containsKey(domain)) {
                result.put(domain, new List<Contact>());
            }
            result.get(domain).add(c);
        }

        return result;
    }

    /**
     * Extracts the lower-cased domain part of an email address.
     *
     * @param email The email address.
     * @return The lower-cased domain, or null if the email is invalid/blank.
     */
    private static String extractDomain(String email) {
        if (String.isBlank(email)) {
            return null;
        }

        Integer atIndex = email.lastIndexOf('@');
        if (atIndex < 0 || atIndex == email.length() - 1) {
            return null;
        }

        return email.substring(atIndex + 1).toLowerCase();
    }
}
