/**
 * RecordSearchService
 *
 * Generic, FLS/CRUD/sharing-aware equality search utility used by the admin
 * "record finder" Lightning component. Builds and executes a single, safe
 * dynamic SOQL query based on caller-supplied object/field names and filter
 * values.
 */
public with sharing class RecordSearchService {

    /**
     * The only exception type ever thrown by this service.
     */
    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // ---- Basic input validation -------------------------------------------------
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be an integer between 1 and 200.');
        }
        if (String.isBlank(objectApiName)) {
            throw new SearchException('An object API name is required.');
        }
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }

        // ---- Object validation --------------------------------------------------------
        Schema.DescribeSObjectResult objDescribe = getObjectDescribe(objectApiName);
        if (objDescribe == null) {
            throw new SearchException('Object "' + objectApiName + '" does not exist or is not accessible.');
        }
        if (!objDescribe.isAccessible()) {
            throw new SearchException('You do not have permission to read object "' + objDescribe.getName() + '".');
        }

        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        // ---- SELECT field validation ----------------------------------------------------
        Set<String> seenLowerCase = new Set<String>();
        List<String> selectFields = new List<String>();
        for (String rawField : fields) {
            Schema.DescribeFieldResult fd = getFieldDescribe(fieldMap, rawField, objDescribe);
            String apiName = fd.getName();
            if (apiName.equalsIgnoreCase('Id')) {
                continue; // Id is always selected explicitly below.
            }
            String key = apiName.toLowerCase();
            if (!seenLowerCase.contains(key)) {
                seenLowerCase.add(key);
                selectFields.add(apiName);
            }
        }

        // ---- Filter validation + bind variable construction ------------------------------
        Map<String, Object> bindMap = new Map<String, Object>();
        List<String> whereClauses = new List<String>();
        if (filters != null && !filters.isEmpty()) {
            Integer bindIndex = 0;
            for (String rawFilterField : filters.keySet()) {
                Schema.DescribeFieldResult fd = getFieldDescribe(fieldMap, rawFilterField, objDescribe);
                if (!fd.isFilterable()) {
                    throw new SearchException(
                        'Field "' + fd.getName() + '" on object "' + objDescribe.getName() + '" cannot be filtered.'
                    );
                }
                String bindName = 'rsFilter' + bindIndex;
                bindIndex++;
                whereClauses.add(fd.getName() + ' = :' + bindName);
                bindMap.put(bindName, filters.get(rawFilterField));
            }
        }

        // ---- ORDER BY validation ----------------------------------------------------------
        String orderByClause = '';
        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult fd = getFieldDescribe(fieldMap, orderByField, objDescribe);
            if (!fd.isSortable()) {
                throw new SearchException(
                    'Field "' + fd.getName() + '" on object "' + objDescribe.getName() + '" cannot be sorted on.'
                );
            }
            orderByClause = ' ORDER BY ' + fd.getName() + ' ASC';
        }

        // ---- Assemble the query -------------------------------------------------------------
        String selectClause = 'Id';
        if (!selectFields.isEmpty()) {
            selectClause += ', ' + String.join(selectFields, ', ');
        }

        String query = 'SELECT ' + selectClause + ' FROM ' + objDescribe.getName();
        if (!whereClauses.isEmpty()) {
            query += ' WHERE ' + String.join(whereClauses, ' AND ');
        }
        query += orderByClause;
        query += ' LIMIT ' + maxRows; // maxRows is a validated Integer literal, safe to inline.

        // ---- Execute with explicit user-mode enforcement (sharing + CRUD/FLS) ----------------
        try {
            return Database.queryWithBinds(query, bindMap, AccessLevel.USER_MODE);
        } catch (SearchException se) {
            throw se;
        } catch (Exception e) {
            throw new SearchException('Unable to execute search: ' + e.getMessage());
        }
    }

    // ------------------------------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------------------------------

    private static Schema.DescribeSObjectResult getObjectDescribe(String objectApiName) {
        Schema.SObjectType sObjType = Schema.getGlobalDescribe().get(objectApiName);
        if (sObjType == null) {
            return null;
        }
        return sObjType.getDescribe();
    }

    private static Schema.DescribeFieldResult getFieldDescribe(
        Map<String, Schema.SObjectField> fieldMap,
        String fieldApiName,
        Schema.DescribeSObjectResult objDescribe
    ) {
        if (String.isBlank(fieldApiName)) {
            throw new SearchException('A field name cannot be blank.');
        }
        Schema.SObjectField field = fieldMap.get(fieldApiName);
        if (field == null) {
            throw new SearchException(
                'Field "' + fieldApiName + '" does not exist on object "' + objDescribe.getName() + '".'
            );
        }
        Schema.DescribeFieldResult fd = field.getDescribe();
        if (!fd.isAccessible()) {
            throw new SearchException(
                'You do not have permission to read field "' + fd.getName() +
                '" on object "' + objDescribe.getName() + '".'
            );
        }
        return fd;
    }
}
