/**
 * Parses e-commerce order JSON payloads posted to an Apex REST endpoint
 * and builds acknowledgement responses.
 */
public class OrderPayloadParser {

    /**
     * Thrown for any problem encountered while parsing an order payload.
     */
    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Request body is empty.');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON payload: ' + e.getMessage());
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Payload must be a JSON object.');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        Order order = new Order();

        Object numberObj = root.get('number');
        if (!(numberObj instanceof String) || String.isBlank((String) numberObj)) {
            throw new PayloadException('Order number is required.');
        }
        order.orderNumber = (String) numberObj;

        Object dateObj = root.get('date');
        if (dateObj != null) {
            if (!(dateObj instanceof String)) {
                throw new PayloadException('Order date must be a string.');
            }
            try {
                order.orderDate = Date.valueOf((String) dateObj);
            } catch (Exception e) {
                throw new PayloadException('Invalid order date: ' + dateObj);
            }
        }

        Object currencyObj = root.get('currency');
        order.currencyCode = (currencyObj instanceof String) ? (String) currencyObj : null;

        Object customerObj = root.get('customer');
        if (customerObj instanceof Map<String, Object>) {
            Map<String, Object> customerMap = (Map<String, Object>) customerObj;
            Object emailObj = customerMap.get('email');
            order.customerEmail = (emailObj instanceof String) ? (String) emailObj : null;
        } else {
            order.customerEmail = null;
        }

        List<Line> parsedLines = new List<Line>();
        Object linesObj = root.get('lines');
        if (linesObj != null) {
            if (!(linesObj instanceof List<Object>)) {
                throw new PayloadException('Lines must be an array.');
            }
            for (Object lineObj : (List<Object>) linesObj) {
                if (!(lineObj instanceof Map<String, Object>)) {
                    throw new PayloadException('Each line must be an object.');
                }
                parsedLines.add(parseLine((Map<String, Object>) lineObj));
            }
        }
        order.lines = parsedLines;

        Decimal total = 0;
        for (Line l : parsedLines) {
            total += l.lineTotal;
        }
        order.total = total.setScale(2, System.RoundingMode.HALF_UP);

        return order;
    }

    private static Line parseLine(Map<String, Object> lineMap) {
        Line line = new Line();

        Object skuObj = lineMap.get('sku');
        if (!(skuObj instanceof String) || String.isBlank((String) skuObj)) {
            throw new PayloadException('Line sku is required.');
        }
        line.sku = (String) skuObj;

        Decimal quantityDec = toDecimal(lineMap.get('quantity'));
        if (quantityDec == null || quantityDec <= 0) {
            throw new PayloadException('Line quantity must be a positive number.');
        }
        line.quantity = quantityDec.intValue();

        Decimal unitPriceDec = toDecimal(lineMap.get('unitPrice'));
        if (unitPriceDec == null || unitPriceDec < 0) {
            throw new PayloadException('Line unitPrice must be a non-negative number.');
        }
        line.unitPrice = unitPriceDec;

        Decimal discountDec = toDecimal(lineMap.get('discount'));
        line.discount = (discountDec == null) ? 0 : discountDec;

        Decimal rawTotal = line.quantity * line.unitPrice * (1 - line.discount);
        line.lineTotal = rawTotal.setScale(2, System.RoundingMode.HALF_UP);

        return line;
    }

    private static Decimal toDecimal(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Double) {
            return Decimal.valueOf(String.valueOf(value));
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        if (value instanceof String) {
            try {
                return Decimal.valueOf((String) value);
            } catch (Exception e) {
                throw new PayloadException('Invalid numeric value: ' + value);
            }
        }
        throw new PayloadException('Invalid numeric value: ' + value);
    }

    public static String toAcknowledgement(Order order) {
        JSONGenerator gen = JSON.createGenerator(false);
        gen.writeStartObject();
        gen.writeStringField('number', order.orderNumber);
        gen.writeStringField('status', 'RECEIVED');
        gen.writeNumberField('lineCount', order.lines != null ? order.lines.size() : 0);
        gen.writeNumberField('total', order.total != null ? order.total : 0);
        gen.writeEndObject();
        return gen.getAsString();
    }
}
