public with sharing class LeadImportService {

    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            this.successCount = 0;
            this.insertedIds = new List<Id>();
            this.errorsByIndex = new Map<Integer, String>();
        }
    }

    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Track which original indices will actually be sent to DML,
        // preserving input order via a list of indices.
        List<Integer> dmlIndices = new List<Integer>();
        List<Lead> dmlLeads = new List<Lead>();
        Set<String> seenEmails = new Set<String>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead ld = leads[i];

            // Default LeadSource
            if (ld.LeadSource == null || String.isBlank(ld.LeadSource)) {
                ld.LeadSource = 'Web';
            }

            String emailKey = null;
            if (ld.Email != null && String.isNotBlank(ld.Email)) {
                emailKey = ld.Email.trim().toLowerCase();
            }

            if (emailKey != null && seenEmails.contains(emailKey)) {
                result.errorsByIndex.put(i, 'Duplicate email in import: ' + emailKey);
                continue;
            }

            if (emailKey != null) {
                seenEmails.add(emailKey);
            }

            dmlIndices.add(i);
            dmlLeads.add(ld);
        }

        if (!dmlLeads.isEmpty()) {
            Database.SaveResult[] saveResults = Database.insert(dmlLeads, false);

            for (Integer j = 0; j < saveResults.size(); j++) {
                Database.SaveResult sr = saveResults[j];
                Integer originalIndex = dmlIndices[j];

                if (sr.isSuccess()) {
                    result.successCount++;
                    result.insertedIds.add(sr.getId());
                } else {
                    List<String> msgs = new List<String>();
                    for (Database.Error err : sr.getErrors()) {
                        msgs.add(err.getMessage());
                    }
                    result.errorsByIndex.put(originalIndex, String.join(msgs, '; '));
                }
            }
        }

        return result;
    }
}
