     * Represents a single active picklist value.
     */
    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    /**
     * Thrown whenever the requested object/field cannot be resolved to an
     * active picklist or multi-select picklist field.
     */
    public class PicklistServiceException extends Exception {}

    /**
     * Returns the active values of the given picklist (or multi-select
     * picklist) field, in field-definition order.
     *
     * @param objectApiName the API name of the object (case-insensitive)
     * @param fieldApiName  the API name of the field (case-insensitive)
     * @return list of active Option values, in defined order
     * @throws PicklistServiceException if either name is blank, the object
     *         does not exist, the field does not exist on the object, or
     *         the field is not a picklist/multi-select picklist.
     */
    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Both objectApiName and fieldApiName must be provided.');
        }

        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType sObjType = globalDescribe.get(objectApiName.trim().toLowerCase());
        if (sObjType == null) {
            throw new PicklistServiceException('Object "' + objectApiName + '" was not found.');
        }

        Schema.DescribeSObjectResult objDescribe;
        try {
            objDescribe = sObjType.getDescribe();
        } catch (Exception e) {
            throw new PicklistServiceException('Unable to describe object "' + objectApiName + '": ' + e.getMessage());
        }

        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();
        Schema.SObjectField field = fieldMap.get(fieldApiName.trim().toLowerCase());
        if (field == null) {
            throw new PicklistServiceException(
                'Field "' + fieldApiName + '" was not found on object "' + objectApiName + '".'
            );
        }

        Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();

        if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field "' + fieldApiName + '" on object "' + objectApiName + '" is not a picklist or multi-select picklist field.'
            );
        }

        List<Option> options = new List<Option>();
        for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
            if (entry.isActive()) {
                options.add(new Option(entry.getValue(), entry.getLabel(), entry.isDefaultValue()));
            }
        }

        return options;
    }
}
