public with sharing class ErpAccountSyncJob implements Queueable {

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer before doing any work so it always runs,
        // whether the job succeeds or fails.
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            accountsToUpdate.add(new Account(
                Id = accId,
                Description = 'Synced to ERP'
            ));
        }

        // All-or-nothing: if any record fails, this throws and the whole
        // job (and transaction) is rolled back. Do not catch the exception
        // here; the finalizer will handle logging and retry.
        update accountsToUpdate;
    }
}
