```apex
/**
 * Keeps Account.FB_Open_Pipeline__c (sum of open Opportunity.Amount, blanks = 0)
 * and Account.FB_Open_Opportunities__c (count of open Opportunities) in sync.
 *
 * The rollups are always *recomputed from scratch* (via an aggregate query) for
 * every Account that could possibly be affected by the triggering DML. This makes
 * the logic idempotent and correct no matter how many times it runs in a single
 * transaction (several DML statements on the same records, Flow + Apex, etc.),
 * and it is immune to drift that an incremental "add/subtract" approach could
 * introduce.
 *
 * Note: this org also has an AccountTrigger that, on every Account update,
 * unconditionally re-saves every open Opportunity for that Account (to copy the
 * Rating onto FB_Account_Rating__c). That means an Account update performed here
 * can cause this trigger to fire again. To avoid an infinite loop we only issue
 * an Account UPDATE when the freshly computed values actually differ from what
 * is currently stored - once the numbers match, the "ping-pong" naturally stops.
 */
public without sharing class OpportunityPipelineHandler {

    public static void handleAfterInsert(List<Opportunity> newOpps) {
        recalculate(collectAccountIds(newOpps));
    }

    public static void handleAfterUpdate(List<Opportunity> newOpps, Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity o : newOpps) {
            if (o.AccountId != null) {
                accountIds.add(o.AccountId);
            }
            Opportunity oldOpp = oldMap.get(o.Id);
            if (oldOpp != null && oldOpp.AccountId != null) {
                accountIds.add(oldOpp.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public static void handleAfterDelete(List<Opportunity> oldOpps) {
        recalculate(collectAccountIds(oldOpps));
    }

    public static void handleAfterUndelete(List<Opportunity> newOpps) {
        recalculate(collectAccountIds(newOpps));
    }

    private static Set<Id> collectAccountIds(List<Opportunity> opps) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity o : opps) {
            if (o.AccountId != null) {
                accountIds.add(o.AccountId);
            }
        }
        return accountIds;
    }

    private static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Aggregate the current open pipeline / count per account in one query.
        Map<Id, AggregateResult> aggByAccountId = new Map<Id, AggregateResult>();
        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) sumAmount, COUNT(Id) cnt
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('AccountId');
            aggByAccountId.put(accId, ar);
        }

        // Current stored values, needed so we only update accounts whose values
        // actually change (breaks the AccountTrigger <-> OpportunityTrigger loop).
        Map<Id, Account> currentAccounts = new Map<Id, Account>([
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]);

        List<Account> toUpdate = new List<Account>();
        for (Id accId : accountIds) {
            Account acc = currentAccounts.get(accId);
            if (acc == null) {
                // Account may have been deleted in the same transaction; nothing to update.
                continue;
            }

            AggregateResult ar = aggByAccountId.get(accId);

            Decimal newPipeline = 0;
            Integer newCount = 0;
            if (ar != null) {
                Object sumRaw = ar.get('sumAmount');
                newPipeline = (sumRaw == null) ? 0 : (Decimal) sumRaw;
                Object cntRaw = ar.get('cnt');
                newCount = (cntRaw == null) ? 0 : (Integer) cntRaw;
            }

            Decimal currentPipeline = (acc.FB_Open_Pipeline__c == null) ? 0 : acc.FB_Open_Pipeline__c;
            Integer currentCount = (acc.FB_Open_Opportunities__c == null)
                ? 0
                : acc.FB_Open_Opportunities__c.intValue();

            if (currentPipeline != newPipeline || currentCount != newCount) {
                toUpdate.add(new Account(
                    Id = accId,
                    FB_Open_Pipeline__c = newPipeline,
                    FB_Open_Opportunities__c = newCount
                ));
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
