/**
 * Schedulable job that purges old FB_Integration_Log__c records.
 *
 * Rules:
 *  - Logs with Level__c != 'ERROR' (including blank) are deleted once older than 30 days.
 *  - Logs with Level__c = 'ERROR' are kept until older than 180 days.
 *
 * The actual deletion work is delegated to an inner Batchable class so that the
 * job remains safe regardless of how many records need to be purged (governor
 * limits on SOQL rows / DML records per transaction are respected via batching).
 */
public class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext sc) {
        Database.executeBatch(new LogPurgeBatch(), 200);
    }

    /**
     * Schedules this job to run nightly at 02:00 under the name
     * "Log purge (nightly)" and returns the Id of the scheduled job (CronTrigger Id).
     */
    public static Id scheduleNightly() {
        String cronExpression = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }

    /**
     * Batchable worker that performs the actual deletion in bulk-safe chunks.
     */
    public class LogPurgeBatch implements Database.Batchable<SObject>, Database.Stateless {

        public Database.QueryLocator start(Database.BatchableContext bc) {
            DateTime cutoffStandard = DateTime.now().addDays(-30);
            DateTime cutoffError = DateTime.now().addDays(-180);

            String query =
                'SELECT Id FROM FB_Integration_Log__c ' +
                'WHERE ((Level__c != \'ERROR\' OR Level__c = null) AND CreatedDate < :cutoffStandard) ' +
                'OR (Level__c = \'ERROR\' AND CreatedDate < :cutoffError)';

            return Database.getQueryLocator(query);
        }

        public void execute(Database.BatchableContext bc, List<SObject> scope) {
            delete scope;
        }

        public void finish(Database.BatchableContext bc) {
        }
    }
}
