/**
 * Selector for Account.
 *
 * - Always selects Id, Name, Industry plus whatever fields are currently
 *   configured on the Credit_Review field set (so admins can extend the
 *   field set without any Apex changes).
 * - Runs every query WITH USER_MODE, enforced via the selector's data
 *   access setting, so object/field/sharing access is enforced for the
 *   running user and an exception is thrown instead of silently
 *   dropping inaccessible data.
 */
public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    public AccountsSelector() {
        super();
        setDataAccess(fflib_SObjectSelector.DataAccess.USER_MODE);
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
    }

    public List<Schema.FieldSet> getSObjectFieldSetList() {
        return new List<Schema.FieldSet>{
            SObjectType.Account.fieldSets.Credit_Review
        };
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        fflib_QueryFactory accountQueryFactory = newQueryFactory();

        new ContactsSelector().addQueryFactorySubselect(accountQueryFactory);

        accountQueryFactory.setCondition('Id in :accountIds');

        return (List<Account>) Database.query(accountQueryFactory.toSOQL());
    }
}
