public with sharing class CasePriorityHandler {

    private static final String RATING_HOT = 'Hot';
    private static final String PRIORITY_HIGH = 'High';

    /**
     * For cases created against an Account with Rating = 'Hot',
     * force Priority to 'High'. All other cases keep whatever
     * Priority they were created with (including cases with no Account).
     *
     * Bulk-safe: a single SOQL query handles the whole batch (up to 200
     * records from the ERP integration, or a single record from
     * Email-to-Case), instead of querying per-record inside the loop,
     * which would risk hitting the 100-SOQL-queries-per-transaction limit.
     */
    public static void setPriorityForHotAccounts(List<Case> newCases) {

        // Collect the distinct, non-null AccountIds referenced by the new cases.
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return; // No accounts to check, nothing to do.
        }

        // One query for the whole batch, instead of one query per case.
        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Rating FROM Account WHERE Id IN :accountIds]
        );

        for (Case c : newCases) {
            if (c.AccountId == null) {
                continue;
            }

            Account acc = accountsById.get(c.AccountId);
            if (acc != null && acc.Rating == RATING_HOT) {
                c.Priority = PRIORITY_HIGH;
            }
            // Otherwise, leave Priority exactly as it was created.
        }
    }
}
