/**
 * Keeps Account.Rating in sync with each account's open pipeline:
 *   - Hot  : at least one open opportunity with Amount >= 100,000
 *   - Warm : open opportunities exist, but none reach 100,000
 *   - Cold : no open opportunities
 *
 * Runs asynchronously (future) so Opportunity DML stays fast, and is
 * bulkified to safely handle large sets of accounts coming from a
 * single Opportunity trigger invocation (e.g. CPQ batches of 200).
 */
public without sharing class AccountRatingService {

    private static final Decimal HOT_THRESHOLD = 100000;

    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Map<Id, Decimal> maxOpenAmountByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> openCountByAccount = new Map<Id, Integer>();

        for (AggregateResult ar : [
            SELECT AccountId, MAX(Amount) maxAmt, COUNT(Id) cnt
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('AccountId');
            maxOpenAmountByAccount.put(accId, (Decimal) ar.get('maxAmt'));
            openCountByAccount.put(accId, (Integer) ar.get('cnt'));
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Id accId : accountIds) {
            Integer openCount = openCountByAccount.containsKey(accId)
                ? openCountByAccount.get(accId)
                : 0;

            String newRating;

            if (openCount == 0) {
                newRating = 'Cold';
            } else {
                Decimal maxAmt = maxOpenAmountByAccount.get(accId);
                newRating = (maxAmt != null && maxAmt >= HOT_THRESHOLD)
                    ? 'Hot'
                    : 'Warm';
            }

            accountsToUpdate.add(new Account(Id = accId, Rating = newRating));
        }

        if (accountsToUpdate.isEmpty()) {
            return;
        }

        List<Database.SaveResult> results = Database.update(accountsToUpdate, false);

        for (Database.SaveResult sr : results) {
            if (!sr.isSuccess()) {
                for (Database.Error err : sr.getErrors()) {
                    System.debug(
                        LoggingLevel.ERROR,
                        'AccountRatingService failed to update Rating for Account '
                            + sr.getId() + ': ' + err.getStatusCode() + ' - ' + err.getMessage()
                    );
                }
            }
        }
    }
}
