public with sharing class LineItemDiscountHandler {

    /**
     * For any new OpportunityLineItem without an explicit Discount
     * (null means "not set" - a rep-entered 0 is preserved), apply the
     * standard discount for its product, as defined by PricingRules.
     *
     * PricingRules.standardDiscountFor() runs a SOQL query per call, so to
     * stay bulk-safe for CPQ batches of up to 200 lines we call it once per
     * distinct Product2Id rather than once per line, and reuse the cached
     * result for every line that shares that product.
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> newLines) {
        Set<Id> productIdsNeedingDiscount = new Set<Id>();

        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIdsNeedingDiscount.add(line.Product2Id);
            }
        }

        if (productIdsNeedingDiscount.isEmpty()) {
            return;
        }

        Map<Id, Decimal> standardDiscountByProductId = new Map<Id, Decimal>();
        for (Id productId : productIdsNeedingDiscount) {
            standardDiscountByProductId.put(productId, PricingRules.standardDiscountFor(productId));
        }

        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                line.Discount = standardDiscountByProductId.get(line.Product2Id);
            }
        }
    }
}
