/**
 * Matches Leads to existing Contacts by email address.
 *
 * Matching rules:
 *  - Comparison ignores case and leading/trailing whitespace.
 *  - A Lead or Contact with a blank (null/empty/whitespace-only) email never matches.
 *  - When multiple Contacts share the same email, the first one encountered in
 *    the `contacts` list (in the order supplied) is returned.
 *  - The result list has the same size and order as `leads`: index i of the
 *    result corresponds to leads[i]. A null entry means no match was found.
 *
 * This class performs no SOQL queries and no DML; it only reads the lists
 * passed in. It is safe to call from within any transaction, including
 * trigger context, without consuming additional query/DML limits.
 */
public with sharing class LeadContactMatcher {

    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> results = new List<Id>();

        if (leads == null) {
            return results;
        }

        // Build a lookup of normalized email -> first matching Contact Id.
        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        if (contacts != null) {
            for (Contact c : contacts) {
                String normalizedEmail = normalize(c.Email);
                if (normalizedEmail == null) {
                    continue;
                }
                // Keep only the first contact seen for a given email.
                if (!contactIdByEmail.containsKey(normalizedEmail)) {
                    contactIdByEmail.put(normalizedEmail, c.Id);
                }
            }
        }

        for (Lead l : leads) {
            String normalizedEmail = normalize(l.Email);
            Id matchedContactId = (normalizedEmail == null)
                ? null
                : contactIdByEmail.get(normalizedEmail);
            results.add(matchedContactId);
        }

        return results;
    }

    /**
     * Trims and lowercases the given email for comparison purposes.
     * Returns null if the email is null, empty, or blank after trimming.
     */
    private static String normalize(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }
}
