public with sharing class AccountCountrySync {

    /**
     * After-update entry point.
     * For every account whose BillingCountry changed, propagate the new
     * BillingCountry to that account's contacts whose MailingCountry is
     * blank or equal to the account's *previous* BillingCountry.
     *
     * Bulk-safe: a single SOQL query, scoped to the accounts in this
     * trigger batch (not the entire Contact table), followed by a single
     * bulk DML update.
     */
    public static void handleAfterUpdate(List<Account> newAccounts, Map<Id, Account> oldAccountMap) {

        // Step 1: identify accounts in this batch whose BillingCountry actually changed.
        // Pure in-memory work on trigger context - no query needed here.
        Map<Id, String> newCountryByAccountId = new Map<Id, String>();
        Map<Id, String> oldCountryByAccountId = new Map<Id, String>();

        for (Account acc : newAccounts) {
            Account oldAcc = oldAccountMap.get(acc.Id);
            if (acc.BillingCountry != oldAcc.BillingCountry) {
                newCountryByAccountId.put(acc.Id, acc.BillingCountry);
                oldCountryByAccountId.put(acc.Id, oldAcc.BillingCountry);
            }
        }

        // Nothing changed for any account in this batch - nothing to do.
        if (newCountryByAccountId.isEmpty()) {
            return;
        }

        // Step 2: single query, scoped to only the accounts that changed in this batch
        // (at most 200, per the MDM integration's batch size). This deliberately avoids
        // querying the entire Contact table (2.3M rows), which would exceed the 50,000
        // row SOQL limit and blow the heap size limit.
        List<Contact> contactsToCheck = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :newCountryByAccountId.keySet()
        ];

        // Step 3: apply the business rule in memory, no further queries.
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact con : contactsToCheck) {
            String newCountry = newCountryByAccountId.get(con.AccountId);
            String oldCountry = oldCountryByAccountId.get(con.AccountId);

            Boolean eligible = (con.MailingCountry == null) || (con.MailingCountry == oldCountry);

            if (eligible && con.MailingCountry != newCountry) {
                con.MailingCountry = newCountry;
                contactsToUpdate.add(con);
            }
        }

        // Step 4: single bulk DML.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
