import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    error;

    debounceTimer = null;
    requestSequence = 0;
    isComponentConnected = false;

    connectedCallback() {
        this.isComponentConnected = true;
    }

    disconnectedCallback() {
        this.isComponentConnected = false;
        this.clearPendingDebounce();
    }

    handleChange(event) {
        const rawValue = event.target.value || '';
        const trimmedValue = rawValue.trim();

        // Cancel any pending debounced search whenever input changes.
        this.clearPendingDebounce();

        if (trimmedValue.length < MIN_SEARCH_LENGTH) {
            this.contacts = [];
            this.error = undefined;
            return;
        }

        this.debounceTimer = setTimeout(() => {
            this.debounceTimer = null;
            this.executeSearch(trimmedValue);
        }, DEBOUNCE_DELAY);
    }

    executeSearch(searchTerm) {
        const currentRequest = ++this.requestSequence;

        searchContacts({ searchTerm })
            .then((result) => {
                if (!this.isComponentConnected || currentRequest !== this.requestSequence) {
                    return;
                }
                this.contacts = result || [];
                this.error = undefined;
            })
            .catch((error) => {
                if (!this.isComponentConnected || currentRequest !== this.requestSequence) {
                    return;
                }
                this.contacts = [];
                this.error =
                    (error && error.body && error.body.message) ||
                    'An unknown error occurred while searching contacts.';
            });
    }

    clearPendingDebounce() {
        if (this.debounceTimer) {
            clearTimeout(this.debounceTimer);
            this.debounceTimer = null;
        }
    }

    get hasContacts() {
        return this.contacts && this.contacts.length > 0;
    }

    get hasError() {
        return !!this.error;
    }
}
