```javascript
import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    error;
    hasData = false;

    isLoading = false;
    intervalId;
    boundVisibilityChangeHandler;

    connectedCallback() {
        this.boundVisibilityChangeHandler = this.handleVisibilityChange.bind(this);
        document.addEventListener('visibilitychange', this.boundVisibilityChangeHandler);

        this.loadStats();
        this.startPolling();
    }

    disconnectedCallback() {
        this.stopPolling();

        if (this.boundVisibilityChangeHandler) {
            document.removeEventListener('visibilitychange', this.boundVisibilityChangeHandler);
            this.boundVisibilityChangeHandler = undefined;
        }
    }

    startPolling() {
        this.stopPolling();
        this.intervalId = setInterval(() => {
            this.loadStats();
        }, REFRESH_INTERVAL_MS);
    }

    stopPolling() {
        if (this.intervalId) {
            clearInterval(this.intervalId);
            this.intervalId = undefined;
        }
    }

    handleVisibilityChange() {
        if (document.visibilityState === 'visible') {
            this.loadStats();
            // Restart the polling cadence so the next automatic refresh
            // happens a full interval from the moment the tab became visible.
            this.startPolling();
        }
    }

    loadStats() {
        if (this.isLoading) {
            // A request is already in flight; skip this refresh.
            return;
        }

        if (document.visibilityState === 'hidden') {
            // Tab is in the background; don't make requests.
            return;
        }

        this.isLoading = true;

        getQueueStats()
            .then((result) => {
                this.waiting = result.waiting;
                this.longestWaitMinutes = result.longestWaitMinutes;
                this.hasData = true;
                this.error = undefined;
            })
            .catch((error) => {
                this.error = error;
            })
            .finally(() => {
                this.isLoading = false;
            });
    }

    get hasError() {
        return !!this.error;
    }

    get errorMessage() {
        return this.error && this.error.body && this.error.body.message
            ? this.error.body.message
            : 'An unknown error occurred.';
    }
}
