import { LightningElement, api } from 'lwc';

let nextInstanceId = 0;

const NAV_KEYS = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

export default class StatusListbox extends LightningElement {
    @api label;
    @api options = [];

    _value = '';
    _activeValue = '';

    baseId = `status-listbox-${nextInstanceId++}`;

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val || '';
        // Parent-driven change moves the active option to the new value.
        this._activeValue = this._value;
    }

    get safeOptions() {
        return this.options || [];
    }

    get activeOptionValue() {
        if (this._activeValue) {
            return this._activeValue;
        }
        const opts = this.safeOptions;
        return opts.length > 0 ? opts[0].value : '';
    }

    get listOptions() {
        return this.safeOptions.map((opt, index) => {
            const id = `${this.baseId}-option-${index}`;
            const isSelected = opt.value === this._value;
            return {
                id,
                value: opt.value,
                label: opt.label,
                ariaSelected: isSelected ? 'true' : 'false'
            };
        });
    }

    get activeDescendantId() {
        const activeOpt = this.listOptions.find(
            (o) => o.value === this.activeOptionValue
        );
        return activeOpt ? activeOpt.id : undefined;
    }

    handleKeyDown(event) {
        const key = event.key;
        if (!NAV_KEYS.includes(key)) {
            return;
        }
        event.preventDefault();

        const opts = this.safeOptions;
        if (opts.length === 0) {
            return;
        }

        let currentIndex = opts.findIndex(
            (opt) => opt.value === this.activeOptionValue
        );
        if (currentIndex === -1) {
            currentIndex = 0;
        }

        switch (key) {
            case 'ArrowDown':
                if (currentIndex < opts.length - 1) {
                    currentIndex += 1;
                }
                this._activeValue = opts[currentIndex].value;
                break;
            case 'ArrowUp':
                if (currentIndex > 0) {
                    currentIndex -= 1;
                }
                this._activeValue = opts[currentIndex].value;
                break;
            case 'Home':
                currentIndex = 0;
                this._activeValue = opts[currentIndex].value;
                break;
            case 'End':
                currentIndex = opts.length - 1;
                this._activeValue = opts[currentIndex].value;
                break;
            case 'Enter':
            case ' ':
                this.selectOption(opts[currentIndex].value);
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const value = event.currentTarget.dataset.value;
        this._activeValue = value;
        this.selectOption(value);
    }

    selectOption(value) {
        if (value === this._value) {
            return;
        }
        this._value = value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value }
            })
        );
    }
}
