import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;

    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this._tasks;
    }
    set tasks(value) {
        this._tasks = value;
        // Work on our own copy: never reference the parent's array or objects.
        this.items = (value || []).map((task) => ({ ...task }));
    }

    get headingDisplay() {
        return this.heading ? this.heading.toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return;
        }
        const newTask = { id: `new-${this.nextId++}`, label, done: false };
        this.items = [...this.items, newTask];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        this.items = this.items.map((task) =>
            task.id === id ? { ...task, done: !task.done } : task
        );
    }
}
