```apex
/**
 * Keeps each Contact's "current employer" Affiliation in sync with data captured on the
 * nonprofit's web form.
 *
 * For every Contact/Organization pair supplied:
 *  - if the Organization is already the Contact's primary affiliation, nothing is done;
 *  - otherwise a new Current, Primary npe5__Affiliation__c record is inserted between the
 *    Contact and the Organization. NPSP's standard Affiliations trigger handler
 *    (AFFL_Affiliations_TDTM) then:
 *      - updates Contact.npsp__Primary_Affiliation__c to point at the new Organization, and
 *      - demotes any previous primary Affiliation for that Contact to Status = 'Former',
 *        Primary__c = false, and End Date = today.
 *
 * The Contact's Household Account membership (Contact.AccountId) is never touched, so the
 * Contact always stays in their household.
 *
 * Bulk safe: handles up to 200 Contacts using at most 1 SOQL query and 1 DML statement of
 * its own (NPSP's own trigger logic runs additional, separate operations as part of the
 * same transaction).
 */
public with sharing class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // SOQL #1: load the current primary affiliation for every Contact involved.
        Map<Id, Contact> contactsById = new Map<Id, Contact>(
            [SELECT Id, npsp__Primary_Affiliation__c
             FROM Contact
             WHERE Id IN :employerByContactId.keySet()]
        );

        List<npe5__Affiliation__c> affiliationsToInsert = new List<npe5__Affiliation__c>();

        for (Id contactId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(contactId);
            if (orgId == null) {
                continue;
            }

            Contact c = contactsById.get(contactId);
            if (c == null) {
                continue;
            }

            // Already the contact's primary employer - nothing to do, avoid duplicates.
            if (c.npsp__Primary_Affiliation__c == orgId) {
                continue;
            }

            affiliationsToInsert.add(new npe5__Affiliation__c(
                npe5__Contact__c      = contactId,
                npe5__Organization__c = orgId,
                npe5__Status__c       = 'Current',
                npe5__Primary__c      = true,
                npe5__StartDate__c    = Date.today(),
                npe5__Role__c         = 'Employee'
            ));
        }

        // DML #1: insert new primary affiliations; NPSP's own automation handles demoting
        // any previous primary affiliation and updating the Contact's lookup field.
        if (!affiliationsToInsert.isEmpty()) {
            insert affiliationsToInsert;
        }
    }
}
