/**
 * Service class to manage percentage-based NPSP GAU Allocations for an Opportunity.
 *
 * Allocations are stored using npsp__Percent__c (not a fixed npsp__Amount__c) so that
 * NPSP's own allocation logic (GAU_Allocations_TDTM) recalculates the npsp__Amount__c
 * automatically whenever the Opportunity Amount changes later on. This class never sets
 * npsp__Amount__c directly, which keeps the allocations "self correcting".
 */
public class GauAllocationService {

    public class AllocationException extends Exception {}

    /**
     * Replaces all existing GAU allocations on the given Opportunity with a new set of
     * percentage-based allocations.
     *
     * @param opportunityId      Id of the Opportunity to allocate.
     * @param percentByGauId     Map of General_Accounting_Unit__c Id -> percent (60 = 60%).
     * @return the newly inserted npsp__Allocation__c records.
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {

        // ---------- Validation (no DML has happened yet) ----------

        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id is required.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU allocation percentage is required.');
        }

        Decimal total = 0;

        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('General Accounting Unit Id cannot be null.');
            }

            Decimal pct = percentByGauId.get(gauId);

            if (pct == null || pct <= 0) {
                throw new AllocationException(
                    'Percentage for General Accounting Unit ' + gauId + ' must be greater than 0.'
                );
            }

            total += pct;
        }

        if (total > 100) {
            throw new AllocationException(
                'Total allocation percentage (' + total + '%) cannot exceed 100%.'
            );
        }

        // ---------- Verify GAUs exist and are active ----------

        Set<Id> gauIds = percentByGauId.keySet();

        Map<Id, npsp__General_Accounting_Unit__c> gauById = new Map<Id, npsp__General_Accounting_Unit__c>(
            [
                SELECT Id, Name, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :gauIds
            ]
        );

        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gauById.get(gauId);

            if (gau == null) {
                throw new AllocationException('General Accounting Unit ' + gauId + ' does not exist.');
            }

            if (gau.npsp__Active__c != true) {
                throw new AllocationException(
                    'General Accounting Unit "' + gau.Name + '" (' + gauId + ') is not active.'
                );
            }
        }

        // ---------- All validation passed: perform the data changes ----------

        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();

        for (Id gauId : percentByGauId.keySet()) {
            npsp__Allocation__c alloc = new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            );
            newAllocations.add(alloc);
        }

        insert newAllocations;

        return newAllocations;
    }
}
