/**
 * Service class used by the event check-in app to register an entire family
 * as a single NPSP Household (Household Account model, automatic naming).
 */
public with sharing class HouseholdService {

    /**
     * Inserts all of the given Contacts so that they belong to ONE new NPSP
     * Household Account, with the first Contact in the list set as the
     * household's primary contact.
     *
     * @param members  New (no Id, no AccountId) Contacts to register.
     * @return the Id of the newly created Household Account.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        // Insert the first (future primary) Contact on its own, with no
        // AccountId. Under the NPSP Household Account model, this triggers
        // NPSP's automatic Household Account creation: a brand-new Account
        // with the Household Account record type is created, the Contact is
        // linked to it, that Contact is set as the household's primary
        // contact (npe01__One2OneContact__c), and the household is named /
        // greeted automatically. We never set the Account name or record
        // type ourselves - NPSP owns that.
        Contact primaryContact = members[0];
        primaryContact.Id = null;
        primaryContact.AccountId = null;
        insert primaryContact;

        // Re-query to pick up the Household Account Id that NPSP assigned.
        Contact insertedPrimary = [
            SELECT Id, AccountId
            FROM Contact
            WHERE Id = :primaryContact.Id
            LIMIT 1
        ];
        Id householdId = insertedPrimary.AccountId;

        // Attach every remaining member to that SAME household by setting
        // AccountId explicitly before insert. Because AccountId is already
        // populated for these Contacts, NPSP will NOT spin up additional
        // Household Accounts for them - it simply recalculates the
        // existing household's name/greetings to reflect all members,
        // leaving no stray/empty households behind.
        List<Contact> otherMembers = new List<Contact>();
        for (Integer i = 1; i < members.size(); i++) {
            Contact c = members[i];
            c.Id = null;
            c.AccountId = householdId;
            otherMembers.add(c);
        }
        if (!otherMembers.isEmpty()) {
            insert otherMembers;
        }

        // Guarantee that the first Contact in the input list remains the
        // household's primary contact, regardless of any re-evaluation NPSP
        // might perform once additional members were added.
        update new Account(
            Id = householdId,
            npe01__One2OneContact__c = insertedPrimary.Id
        );

        return householdId;
    }
}
