/**
 * Service class used by the volunteer app to record donations that have
 * already been received into NPSP (Household Account model, Payments enabled).
 */
public with sharing class GiftService {

    private static final String PRIMARY_CONTACT_ROLE = 'Donor';
    private static final String HOUSEHOLD_MEMBER_ROLE = 'Household Member';
    private static final String CLOSED_WON_STAGE = 'Closed Won';

    /**
     * Records a Closed Won gift for the given contact, crediting the contact's
     * household the way NPSP expects (Opportunity Contact Roles + a single paid
     * Payment record), and returns the new Opportunity Id.
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('contactId is required');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('amount must be a positive, non-zero value');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('giftDate is required');
        }

        List<Contact> primaryContacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (primaryContacts.isEmpty()) {
            throw new IllegalArgumentException('No Contact found for Id: ' + contactId);
        }
        Contact primaryContact = primaryContacts[0];
        if (primaryContact.AccountId == null) {
            throw new IllegalArgumentException(
                'Contact ' + contactId + ' is not associated with a household account'
            );
        }

        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :primaryContact.AccountId
        ];

        Opportunity opp = new Opportunity(
            Name = buildOpportunityName(primaryContact, giftDate),
            AccountId = primaryContact.AccountId,
            npsp__Primary_Contact__c = primaryContact.Id,
            StageName = CLOSED_WON_STAGE,
            CloseDate = giftDate,
            Amount = amount
        );
        insert opp;

        assignContactRoles(opp.Id, primaryContact.Id, householdMembers);
        recordPayment(opp.Id, amount, giftDate);

        return opp.Id;
    }

    private static String buildOpportunityName(Contact c, Date giftDate) {
        return c.FirstName + ' ' + c.LastName + ' Donation ' + formatDate(giftDate);
    }

    private static String formatDate(Date d) {
        return String.valueOf(d.year())
            + '-' + padTwo(d.month())
            + '-' + padTwo(d.day());
    }

    private static String padTwo(Integer n) {
        return n < 10 ? '0' + String.valueOf(n) : String.valueOf(n);
    }

    /**
     * Ensures exactly one Opportunity Contact Role per household member exists
     * on the gift: the gift's contact holds the "Donor" role (and is marked
     * primary), every other household member holds "Household Member". Any
     * roles already created by NPSP automation (or prior runs) are reconciled
     * rather than duplicated.
     */
    private static void assignContactRoles(Id opportunityId, Id primaryContactId, List<Contact> householdMembers) {
        Map<Id, String> desiredRoleByContact = new Map<Id, String>();
        desiredRoleByContact.put(primaryContactId, PRIMARY_CONTACT_ROLE);
        for (Contact c : householdMembers) {
            if (c.Id != primaryContactId) {
                desiredRoleByContact.put(c.Id, HOUSEHOLD_MEMBER_ROLE);
            }
        }

        List<OpportunityContactRole> existingRoles = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
        ];

        Set<Id> handledContacts = new Set<Id>();
        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToDelete = new List<OpportunityContactRole>();

        for (OpportunityContactRole ocr : existingRoles) {
            Boolean isKnownContact = desiredRoleByContact.containsKey(ocr.ContactId);
            Boolean isDuplicateForContact = handledContacts.contains(ocr.ContactId);

            if (!isKnownContact || isDuplicateForContact) {
                // Not part of this household (stale/unexpected), or a duplicate
                // role for a contact we've already reconciled above.
                rolesToDelete.add(ocr);
                continue;
            }

            handledContacts.add(ocr.ContactId);
            String desiredRole = desiredRoleByContact.get(ocr.ContactId);
            Boolean desiredIsPrimary = (ocr.ContactId == primaryContactId);

            if (ocr.Role != desiredRole || ocr.IsPrimary != desiredIsPrimary) {
                ocr.Role = desiredRole;
                ocr.IsPrimary = desiredIsPrimary;
                rolesToUpdate.add(ocr);
            }
        }

        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        for (Id cId : desiredRoleByContact.keySet()) {
            if (!handledContacts.contains(cId)) {
                rolesToInsert.add(new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = cId,
                    Role = desiredRoleByContact.get(cId),
                    IsPrimary = (cId == primaryContactId)
                ));
            }
        }

        if (!rolesToDelete.isEmpty()) {
            delete rolesToDelete;
        }
        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }
        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }
    }

    /**
     * Ensures exactly one Payment record exists for the gift, paid in full on
     * giftDate. Reconciles any Payment that NPSP's automatic payment mapping
     * may have already created instead of inserting a duplicate.
     */
    private static void recordPayment(Id opportunityId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            ORDER BY CreatedDate ASC
        ];

        npe01__OppPayment__c payment;
        List<npe01__OppPayment__c> extraPayments = new List<npe01__OppPayment__c>();

        if (!existingPayments.isEmpty()) {
            payment = existingPayments[0];
            for (Integer i = 1; i < existingPayments.size(); i++) {
                extraPayments.add(existingPayments[i]);
            }
        } else {
            payment = new npe01__OppPayment__c(npe01__Opportunity__c = opportunityId);
        }

        payment.npe01__Payment_Amount__c = amount;
        payment.npe01__Payment_Date__c = giftDate;
        payment.npe01__Scheduled_Date__c = giftDate;
