/**
 * FamilyService
 *
 * Links NPSP Contacts as Parent/Child relationships imported from an external student
 * information system.
 *
 * For each (childId -> parentId) pair supplied, a single npe4__Relationship__c record is
 * inserted with the child as npe4__Contact__c, the parent as npe4__RelatedContact__c, and
 * npe4__Type__c = 'Parent'. NPSP's own relationship automation (TDTM trigger handlers) is
 * responsible for automatically creating/maintaining the reciprocal relationship record on
 * the parent's side (Son / Daughter / Child), based on the org's Relationship Lookup custom
 * settings and the contacts' genders. We therefore only ever insert ONE record ourselves per
 * pair; NPSP creates the second one for us.
 *
 * Bulk-safe: for up to 200 pairs, this uses exactly one SOQL query and at most one DML
 * statement performed by this class's own code (NPSP's automation may perform additional
 * DML, but that is outside of our control/accounting).
 */
public class FamilyService {

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect every Contact Id involved so we can look up any existing relationships
        // between any of these contacts in a single query.
        Set<Id> allContactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null) {
                continue;
            }
            allContactIds.add(childId);
            allContactIds.add(parentId);
        }

        if (allContactIds.isEmpty()) {
            return;
        }

        // Single SOQL query: fetch any existing relationship records between any two of the
        // contacts we care about, in either direction.
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allContactIds
              AND npe4__RelatedContact__c IN :allContactIds
        ]) {
            existingPairKeys.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null) {
                continue;
            }

            String forwardKey = pairKey(childId, parentId);
            String reverseKey = pairKey(parentId, childId);

            // Skip if any relationship already exists between these two contacts
            // (in either direction), so re-running the import is safe.
            if (existingPairKeys.contains(forwardKey) || existingPairKeys.contains(reverseKey)) {
                continue;
            }

            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            ));

            // Guard against duplicate work if the same pair somehow appears twice
            // (defensive; Map keys are already unique so this mainly protects against
            // mirrored duplicate entries in the same call).
            existingPairKeys.add(forwardKey);
            existingPairKeys.add(reverseKey);
        }

        if (!toInsert.isEmpty()) {
            // Single DML statement of our own; NPSP's relationship trigger handler will
            // create the reciprocal (Son/Daughter/Child) record on the parent's side.
            insert toInsert;
        }
    }

    private static String pairKey(Id contactId, Id relatedContactId) {
        return String.valueOf(contactId) + '-' + String.valueOf(relatedContactId);
    }
}
