```apex
/**
 * RecordAccessService
 *
 * Determines, for the running user, which of a given set of record Ids are
 * actually editable - taking into account object permissions, field level
 * security is NOT covered here (UserRecordAccess is record-level only),
 * ownership, sharing rules, role hierarchy, teams, Modify All / View All,
 * permission sets, etc. All of that is exactly what the UserRecordAccess
 * object already calculates for us, so we simply query it.
 */
public with sharing class RecordAccessService {

    // UserRecordAccess requires the query to be filtered by a bounded set of
    // RecordIds (or a single UserId). To stay well within the 20-query
    // budget for up to 2,000 ids, we chunk into batches of 200, which caps
    // us at 10 queries for the maximum allowed input size.
    private static final Integer CHUNK_SIZE = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> result = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        List<Id> idList = new List<Id>(recordIds);

        for (Integer startIndex = 0; startIndex < idList.size(); startIndex += CHUNK_SIZE) {
            Integer endIndex = Math.min(startIndex + CHUNK_SIZE, idList.size());
            List<Id> chunk = new List<Id>();
            for (Integer i = startIndex; i < endIndex; i++) {
                chunk.add(idList[i]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                AND RecordId IN :chunk
                AND HasEditAccess = true
            ]) {
                result.add(access.RecordId);
            }
        }

        return result;
    }
}
