/**
 * Trigger Action Framework action: creates an onboarding Task for the account owner
 * when a new Account is inserted with Type Customer - Direct or Customer - Channel.
 *
 * Registered via the Trigger_Action__mdt record
 * Trigger_Action.TA_Account_CreateOnboardingTask for the After Insert context on Account.
 */
public class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {
    @TestVisible
    private static final Set<String> QUALIFYING_ACCOUNT_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    private static final String TASK_SUBJECT = 'Onboard new customer';
    private static final String TASK_STATUS = 'Not Started';
    private static final String TASK_PRIORITY = 'Normal';
    private static final Integer DUE_DATE_OFFSET_DAYS = 7;

    public void afterInsert(List<SObject> triggerNew) {
        List<Task> tasksToInsert = buildOnboardingTasks((List<Account>) triggerNew);

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }

    private List<Task> buildOnboardingTasks(List<Account> newAccounts) {
        List<Task> tasksToInsert = new List<Task>();
        Date dueDate = Date.today().addDays(DUE_DATE_OFFSET_DAYS);

        for (Account acc : newAccounts) {
            if (QUALIFYING_ACCOUNT_TYPES.contains(acc.Type)) {
                tasksToInsert.add(
                    new Task(
                        Subject = TASK_SUBJECT,
                        WhatId = acc.Id,
                        OwnerId = acc.OwnerId,
                        ActivityDate = dueDate,
                        Status = TASK_STATUS,
                        Priority = TASK_PRIORITY
                    )
                );
            }
        }

        return tasksToInsert;
    }
}
