/**
 * Singleton cache for Account records needed by Contact before-insert trigger actions.
 * The inner Service class is registered as the first Trigger_Action__mdt entry for
 * Contact before insert; it (re)loads the accountsById map on every trigger execution so
 * that later actions in the same run never need to query Account themselves, and so that
 * the map stays fresh even if earlier DML in the same transaction touched other Accounts.
 */
public with sharing class TA_Contact_Queries {
    private static TA_Contact_Queries instance;

    public Map<Id, Account> accountsById { get; private set; }

    private TA_Contact_Queries() {
        this.accountsById = new Map<Id, Account>();
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Trigger action responsible for populating the shared accountsById map.
     * Must run first (lowest Order__c) among the Contact before-insert actions.
     */
    public class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            Set<Id> accountIds = new Set<Id>();
            for (SObject so : triggerNew) {
                Contact c = (Contact) so;
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }

            Map<Id, Account> loadedAccounts = new Map<Id, Account>();
            if (!accountIds.isEmpty()) {
                loadedAccounts = new Map<Id, Account>(
                    [
                        SELECT
                            Id,
                            BillingStreet,
                            BillingCity,
                            BillingPostalCode,
                            BillingCountry,
                            AccountSource
                        FROM Account
                        WHERE Id IN :accountIds
                    ]
                );
            }

            TA_Contact_Queries.getInstance().accountsById = loadedAccounts;
        }
    }
}
